cy from survey_assign_org b left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_investigator_case c on b.id = c.survey_assorg_case_id and c.delete_flag = 0 left join survey_franchisee f on b.survey_org_id = f.id where b.delete_flag = 0 and a.delete_flag = 0 ) t group by t.orgId, t.surveyInfoId ) m group by m.orgId,m.surveyInfoId ) z on a.id = z.surveyInfoId
