select B.id, 2 as consignorOrgAttr, B.entrust_report_end_date as entrustReportEndDate, GROUP_CONCAT(CONCAT(B.province,'_',B.servicesName,'_',B.servicesId,'_',B.num)) as directionNameStrs ,B.entrustMoneyCount, B.entrustTime,B.departmentId,B.departmentName,B.entrustOrgId,B.entrustOrgName,B.claimsNo,B.surveyPerson from ( select a.id, a.entrust_report_end_date, A.province, A.servicesName as servicesName, A.servicesId as servicesId, A.num, A.moneyCount as entrustMoneyCount, s.entrust_org_name AS entrustOrgName, s.claims_no AS claimsNo, c.org_attr, s.entrust_org_id AS entrustOrgId, s.department_id AS departmentId, s.department_name AS departmentName, s.survey_person AS surveyPerson, s.entrust_time AS entrustTime, t.areaType as areaType from survey_risk_case_info a left join ( select d.survey_info_id, d.province_id, d.province, o.services_id, o.services_name as servicesName,o.services_id as servicesId, count(1) num, SUM(d.entrust_money) as moneyCount from survey_case_direction d left join survey_assign_org o on o.delete_flag = 0 and o.survey_info_id = d.survey_info_id and d.survey_org_id = o.survey_org_id where d.delete_flag = 0 group by d.survey_info_id,d.province_id,o.services_id ) A on a.id = A.survey_info_id LEFT JOIN survey_risk_case s ON a.survey_id = s.id LEFT JOIN survey_consignor c ON s.entrust_org_id = c.id AND c.delete_flag = 0 left join ( select a.survey_info_id,max(a.area_type) as areaType from ( select r.id as survey_info_id,(case d.area_type when 1 then (case d.region_type when 5 then 0 else 1 end) else d.area_type end) area_type from survey_case_direction d left join survey_risk_case_info r on d.survey_info_id = r.id left join survey_consignor n on r.entrust_org_id = n.id where d.delete_flag = 0 and r.delete_flag = 0 ) a group by a.survey_info_id ) t on t.survey_info_id = a.id
where a.delete_flag = 0
and c.org_attr = #{consignorOrgAttr,jdbcType=INTEGER}
) B group by B.id order by B.entrustOrgId

