update survey_risk_case_info set
performance_state = #{newPerformanceState,jdbcType=INTEGER}

    ,performance_date = #{dateTime,jdbcType=TIMESTAMP}


    ,performance_id = #{addStaffPerformanceId,jdbcType=BIGINT}


    ,performance_id = null

where performance_state = #{oldPerformanceState,jdbcType=INTEGER}
and date_format(entrust_report_end_date,'%Y-%m') <= #{workTime,jdbcType=VARCHAR}

    and performance_id = #{performanceId,jdbcType=BIGINT}

update survey_risk_case_info s ,(
select #{item.id,jdbcType=BIGINT} as id, #{item.entrustReportEndDate,jdbcType=TIMESTAMP} as entrustReportEndDate, #{item.opinion,jdbcType=VARCHAR} as opinion, #{item.agingDay,jdbcType=INTEGER} as agingDay from dual
) t set s.entrust_report_end_date = t.entrustReportEndDate, s.opinion =t.opinion, s.survey_state = 28, s.survey_state_name = '保司终审通过', s.aging_day = t.agingDay where s.id = t.id

update survey_risk_case_info r left join (
select #{item.surveyInfoId} as survey_info_id,#{item.settlementMoney} as money from dual
) t on r.id = t.survey_info_id set r.entrust_ok_price_1 = t.money,r.entrust_money = t.money where t.survey_info_id is not null

UPDATE survey_risk_case_info
SET
performance_state = #{newPerformanceState,jdbcType=INTEGER}

    ,performance_date = #{dateTime,jdbcType=TIMESTAMP}


    ,performance_id = #{addStaffPerformanceId,jdbcType=BIGINT}


    ,performance_id = null

WHERE
performance_state = #{oldPerformanceState,jdbcType=INTEGER}
AND date_format(entrust_report_end_date,'%Y-%m') <= #{workTime,jdbcType=VARCHAR}
AND id IN (
SELECT sic.survey_info_id
FROM survey_investigator_case sic
WHERE sic.survey_user_id = #{userId,jdbcType=BIGINT}
)

    AND performance_id = #{performanceId,jdbcType=BIGINT}

